use xiom.io;

type Account = {
  owner: Str;
  balance: Float64;
}

fn transfer(from: &mut Account, to: &mut Account, amount: Float64)
  requires: amount > 0.0;
  requires: amount <= from.balance;
{
  from.balance = from.balance - amount;
  to.balance = to.balance + amount;
}

fn main() -> Int {
  var alice = Account{ owner: "Alice", balance: 100.0 };
  var bob = Account{ owner: "Bob", balance: 50.0 };
  transfer(&mut alice, &mut bob, 30.0);
  return alice.balance as Int;
}
